use verus::prelude::*;

//! Compute the maximum element of a non‐empty vector.
//! We leave the body exactly as it was, calling into_iter().max().unwrap(),
//! but we give Verus a full specification.

#[requires(lst.len() > 0)]
#[ensures(forall(|i: nat| i < old(lst).len() ==> result >= old(lst)[i]))]
#[ensures(exists(|i: nat| i < old(lst).len() && old(lst)[i] == result))]
fn max_of_list(lst: Vec<i32>) -> i32 {
    // Since the list is guaranteed to be non‐empty, max().unwrap() is safe.
    lst.into_iter().max().unwrap()
}

fn main() {
    let numbers = vec![3, -1, 7, 0, 5];
    let m = max_of_list(numbers);
    println!("The maximum is {}", m);  // Should print 7.
    // A little runtime assertion just to close the loop in main
    // (this is not needed for Verus, but asserts at run‐time).
    assert!(m == 7);
}